package com.devtunasoft.tuneros.core

import java.io.ByteArrayOutputStream
import java.io.OutputStream
import java.time.Instant
import java.time.LocalDateTime
import java.time.ZoneId
import kotlin.test.Test
import kotlin.test.assertEquals
import kotlin.test.assertFailsWith
import kotlin.test.assertTrue

/**
 * Bounded, deterministic coverage of the timeshift seam. Every input here is synthetic: file names are generated by the
 * ring, and the URL marker is a reserved .invalid fixture, not provider data. Nothing depends on the host clock or zone.
 */
class TimeshiftSeamRegressionTest {
    /** Records only what a ring must account for; never keeps media bytes after a file is deleted. */
    private class TrackingRing : TimeshiftRing {
        private val liveNames = LinkedHashSet<String>()
        val deletedNames = ArrayList<String>()
        val playlists = ArrayList<String>()

        override fun create(fileName: String): OutputStream {
            check(liveNames.add(fileName)) { "created twice: $fileName" }
            return ByteArrayOutputStream()
        }

        override fun delete(fileName: String) {
            liveNames.remove(fileName)
            deletedNames += fileName
        }

        override fun replacePlaylist(text: String) {
            playlists += text
        }

        fun live(): Set<String> = liveNames
    }

    private fun segment(sequence: Long, bytes: Long = 1, duration: Double = 2.0) =
        TimeshiftWindow.Segment(sequence, duration, bytes, "seg-$sequence.ts")

    @Test fun retainedBytesNeverOverflowAnAdversarialBudget() {
        val budget = Long.MAX_VALUE
        val window = TimeshiftWindow(maxSegments = 4, maxBytes = budget)
        window.add(segment(0, bytes = budget - 1))
        val left = window.add(segment(1, bytes = budget - 1))

        assertEquals(listOf(0L), left.map { it.sequence }, "the first segment must leave before the budget is exceeded")
        assertEquals(listOf(1L), window.segments().map { it.sequence })
        assertEquals(budget - 1, window.bytes)
        assertTrue(window.bytes <= budget, "retained bytes must never exceed the budget")
    }

    @Test fun repeatedCaptureCyclesKeepBothTheWindowAndTheRingBounded() {
        val ring = TrackingRing()
        val capture = TimeshiftCapture(TimeshiftWindow(maxSegments = 8, maxBytes = 1_000), ring)
        repeat(2_000) { sequence ->
            capture.output.write(sequence)
            capture.onSegmentComplete(sequence.toLong(), 2.0, 1, discontinuity = false)
        }

        val beforeFinish = ring.playlists.last()
        assertEquals(8, beforeFinish.lines().count { it.startsWith("seg-") }, "the window holds no more than its segment limit")
        assertEquals(2_000, ring.playlists.size, "one playlist write per completed segment")
        assertTrue(ring.live().size <= 9, "at most the window plus the open file: ${ring.live().size}")
        assertTrue(ring.deletedNames.size == 1_992, "excess files are deleted as they leave: ${ring.deletedNames.size}")
        val last = ring.playlists.last()
        assertTrue(last.contains("#EXT-X-MEDIA-SEQUENCE:1992\n"), last)
        assertTrue(last.lines().count { it.startsWith("seg-") } == 8, last)
        assertTrue(!last.contains("#EXT-X-ENDLIST"), last)
        capture.finish()
        assertTrue(ring.live().isEmpty(), "finish leaves nothing on disk: ${ring.live()}")
    }

    @Test fun aMalformedSegmentCannotOrphanTheFileBeingWritten() {
        val ring = TrackingRing()
        val capture = TimeshiftCapture(TimeshiftWindow(maxSegments = 4, maxBytes = 1_000), ring)
        capture.output.write(7)
        assertFailsWith<IllegalArgumentException> {
            capture.onSegmentComplete(0, Double.NaN, 1, discontinuity = false)
        }
        capture.finish()

        assertTrue(ring.live().isEmpty(), "a rejected segment must not leave untracked disk: ${ring.live()}")
        assertTrue(ring.playlists.last().let { !it.contains("EXTINF") }, "the playlist must list nothing after finish")
    }

    @Test fun emptyAndSingleItemWindowsKeepExactPlaylistEdges() {
        val empty = TimeshiftWindow(maxSegments = 1, maxBytes = 1)
        assertEquals("#EXTM3U\n#EXT-X-VERSION:3\n#EXT-X-TARGETDURATION:1\n#EXT-X-MEDIA-SEQUENCE:0\n", empty.playlist())

        val single = TimeshiftWindow(maxSegments = 1, maxBytes = 1)
        single.add(TimeshiftWindow.Segment(41, 0.25, 1, "seg-41.ts", programDateMillis = 0L))
        val playlist = single.playlist()
        assertTrue(playlist.contains("#EXT-X-TARGETDURATION:1\n#EXT-X-MEDIA-SEQUENCE:41\n"), playlist)
        assertTrue(playlist.contains("#EXT-X-PROGRAM-DATE-TIME:1970-01-01T00:00:00.000Z\n"), playlist)
        assertEquals(listOf("#EXTINF:0.250,", "seg-41.ts"), playlist.lines().filter {
            it.startsWith("#EXTINF") || it.startsWith("seg-")
        })
        val left = single.add(segment(42, bytes = 1))
        assertEquals(listOf(41L), left.map { it.sequence })
        assertEquals(1, single.size)
        assertEquals(1L, single.bytes)
    }

    @Test fun programDatesStayUnambiguousAcrossADstOverlap() {
        val zone = ZoneId.of("America/Chicago")
        val overlap = LocalDateTime.of(2023, 11, 5, 1, 30)
        val first = overlap.atZone(zone).withEarlierOffsetAtOverlap().toInstant()
        val second = overlap.atZone(zone).withLaterOffsetAtOverlap().toInstant()
        assertEquals(first, Instant.parse("2023-11-05T06:30:00Z"))
        assertEquals(second, Instant.parse("2023-11-05T07:30:00Z"))

        val window = TimeshiftWindow(maxSegments = 2, maxBytes = 100)
        window.add(TimeshiftWindow.Segment(0, 2.0, 1, "seg-0.ts", programDateMillis = first.toEpochMilli()))
        window.add(TimeshiftWindow.Segment(1, 2.0, 1, "seg-1.ts", programDateMillis = second.toEpochMilli()))
        val playlist = window.playlist()
        assertTrue(playlist.contains("#EXT-X-PROGRAM-DATE-TIME:2023-11-05T06:30:00.000Z\n"), playlist)
        assertTrue(playlist.contains("#EXT-X-PROGRAM-DATE-TIME:2023-11-05T07:30:00.000Z\n"), playlist)
        assertEquals(2, playlist.lines().count { it.startsWith("#EXT-X-PROGRAM-DATE-TIME:") })
    }

    @Test fun diagnosticsAndPlaylistsNeverEchoProviderMarkers() {
        val marker = "fixture.invalid"
        val signature = "MARKER_NOT_A_SECRET"
        val syntheticUrl = "https://$marker/live.m3u8?sig=$signature"
        val source = object : HlsCaptureSource {
            override fun loadPlaylist(url: String, afterSequenceExclusive: Long?): LoadedHlsPlaylist {
                // A malformed segment makes the engine stop with a structured detail, without echoing the URL.
                val bad = HlsSegment(0L, "0.ts", null, null, false, "NONE", null, null)
                return LoadedHlsPlaylist(url, HlsMediaPlaylist(0L, 2L, false, listOf(bad)))
            }
            override fun copySegment(
                url: String,
                byteRange: HlsByteRange?,
                output: OutputStream,
                cancelled: () -> Boolean,
                onProgress: (Long) -> Unit,
            ): StreamRecorder.Result = error("this fixture never copies a segment")
            override fun loadKey(url: String): ByteArray = error("this fixture has no keys")
        }
        val ring = TrackingRing()
        val capture = TimeshiftCapture(TimeshiftWindow(maxSegments = 2, maxBytes = 100), ring)
        val result = HlsCaptureEngine().record(
            syntheticUrl, capture.output, 1_000, source, { false }, { 100 }, {}, segmentListener = capture,
        )
        assertEquals(HlsCaptureEngine.StopReason.UNSUPPORTED, result.stopReason)
        val detail = result.detail.orEmpty()
        assertTrue(!detail.contains(marker) && !detail.contains(signature), "structured detail leaked the URL: $detail")
        capture.finish()
        val playlist = ring.playlists.last()
        assertTrue(!playlist.contains(marker) && !playlist.contains(signature), "playlist leaked the URL: $playlist")

        val afterFinish = capture.output
        val message = assertFailsWith<IllegalStateException> { afterFinish.write(1) }.message.orEmpty()
        assertTrue(!message.contains(marker) && !message.contains(signature), "error leaked the URL: $message")
    }

    @Test fun malformedFileNamesAreRefusedAtTheCoreSeam() {
        listOf(".", "..", "sub\\seg.ts").forEach { name ->
            assertFailsWith<IllegalArgumentException>("name accepted: $name") {
                TimeshiftWindow.Segment(0, 2.0, 1, name)
            }
        }
    }
}
